/**
 * Pre-rendered MultiMind metadata artwork. These strings contain PNG image
 * bytes, not font files. Keeping the images in the server bundle avoids file
 * paths, runtime ImageResponse/OG rendering, and network font downloads.
 * This module must only be imported by the metadata image handlers.
 */
import { Buffer } from 'node:buffer';

const PNG = Object.freeze({
  "icon": "",
  "apple": "",
  "opengraph": ""
});

/** Return a fresh response for every request; a consumed stream is never reused. */
export function brandImageResponse(name) {
  if (!Object.prototype.hasOwnProperty.call(PNG, name)) {
    throw new RangeError('Unknown metadata image');
  }
  return new Response(Buffer.from(PNG[name], 'base64'), {
    status: 200,
    headers: {
      'Content-Type': 'image/png',
      'Cache-Control': 'public, max-age=0, must-revalidate',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}
